<script setup lang="ts">
import { displayError } from '~/utils/errors';
const name = ref(''); const email = ref(''); const password = ref(''); const consent = ref(false); const showPassword = ref(false); const message = ref(''); const success = ref(false); const requestId = ref<string>();
const { register, pending } = useAuth();
async function submit() { message.value = ''; requestId.value = undefined; if (name.value.length > 150) { message.value = 'Nama maksimal 150 karakter.'; return; } if (password.value.length < 12) { message.value = 'Password minimal 12 karakter.'; return; } if (!consent.value) { message.value = 'Anda perlu menyetujui Syarat & Ketentuan dan Kebijakan Privasi.'; return; } try { await register(name.value, email.value, password.value); success.value = true; } catch (error) { const shown = displayError(error, 'Pendaftaran belum dapat diproses.'); message.value = shown.message; requestId.value = shown.requestId; } }
useSeoMeta({ title: 'Daftar — Niaga' });
</script>
<template><main id="main-content" class="auth-shell"><section v-if="success" class="auth-card" aria-live="polite"><p class="eyebrow">Pendaftaran berhasil</p><h1>Periksa email Anda</h1><p>Kami mengirim tautan verifikasi ke <strong>{{ email }}</strong>. Buka tautan tersebut sebelum masuk.</p><NuxtLink class="button" to="/login">Ke halaman masuk</NuxtLink></section><form v-else class="auth-card" novalidate @submit.prevent="submit"><p class="eyebrow">Mulai berbelanja</p><h1>Buat akun Niaga</h1><label class="form-field">Nama lengkap<input v-model.trim="name" required maxlength="150" autocomplete="name"></label><label class="form-field">Email<input v-model.trim="email" required type="email" autocomplete="email" placeholder="nama@email.com"></label><label class="form-field">Password<div class="input-action"><input v-model="password" required :type="showPassword ? 'text' : 'password'" minlength="12" autocomplete="new-password"><button type="button" :aria-pressed="showPassword" @click="showPassword = !showPassword">{{ showPassword ? 'Sembunyi' : 'Lihat' }}</button></div></label><p class="form-help">Minimal 12 karakter. Gunakan frasa yang panjang dan unik.</p><label class="checkbox"><input v-model="consent" type="checkbox" required><span>Saya menyetujui <NuxtLink to="/kebijakan/syarat-ketentuan">Syarat & Ketentuan</NuxtLink> dan <NuxtLink to="/kebijakan/privasi">Kebijakan Privasi</NuxtLink>.</span></label><div v-if="message" class="error" role="alert"><strong>{{ message }}</strong><small v-if="requestId"><br>ID permintaan: {{ requestId }}</small></div><button :disabled="pending || !name || !email || password.length < 12 || !consent" type="submit">{{ pending ? 'Membuat akun…' : 'Daftar' }}</button><p class="muted">Sudah punya akun? <NuxtLink to="/login">Masuk</NuxtLink></p></form></main></template>
